   register(ball(g,q.x,q.y,q.z,1.7,'#ffffff',{transparent:true,opacity:0,depthWrite:false}),info);
   const l=label([q.x,q.y+2,q.z],()=>info.name,()=>selectInfo(info),pilot?'pilotLabel':'');l.line=i;l.pilot=pilot;l.code=st.code;l.offsetY=pilot?(st.code==='E15'?-8:-40):(parseInt(st.code.slice(1))%2?-8:-26);
   const disc=new THREE.Mesh(new THREE.RingGeometry(1.1,2.3,16),new THREE.MeshBasicMaterial({color:'#e3f260',transparent:true,opacity:.55,side:THREE.DoubleSide,depthWrite:false}));disc.rotation.x=-Math.PI/2;disc.position.copy(q);disc.userData.line=i;heatGroup.add(disc);
